python3 - <<'PY'
import os
import urllib.request
import xml.etree.ElementTree as ET
from osgeo import ogr, osr

capabilities_url = 'https://geos1.snitcr.go.cr/Ortofoto1k/wmts?SERVICE=WMTS&REQUEST=GetCapabilities&VERSION=1.0.0'
raw = urllib.request.urlopen(capabilities_url, timeout=120).read()
root = ET.fromstring(raw)
ns = {'wmts': 'http://www.opengis.net/wmts/1.0', 'ows': 'http://www.opengis.net/ows/1.1'}
layer_id = 'ortofoto2017_1000'
layer = None
for candidate in root.findall('.//wmts:Contents/wmts:Layer', ns):
    ident = candidate.find('ows:Identifier', ns)
    if ident is not None and ident.text == layer_id:
        layer = candidate
        break
if layer is None:
    raise RuntimeError('Orthophoto layer not found')
linked = [e.text for e in layer.findall('wmts:TileMatrixSetLink/wmts:TileMatrixSet', ns)]
matrix_sets = {}
for tms in root.findall('.//wmts:Contents/wmts:TileMatrixSet', ns):
    ident = tms.find('ows:Identifier', ns)
    crs = tms.find('ows:SupportedCRS', ns)
    if ident is not None:
        matrix_sets[ident.text] = '' if crs is None else (crs.text or '')
chosen = next((x for x in linked if '5367' in matrix_sets.get(x, '')), None)
if chosen is None:
    chosen = next((x for x in linked if '3857' in matrix_sets.get(x, '')), None)
if chosen is None and linked:
    chosen = linked[0]
if chosen is None:
    raise RuntimeError('No TileMatrixSet available')
print('Selected TileMatrixSet:', chosen, matrix_sets.get(chosen, ''))
with open('wmts.xml', 'w', encoding='utf-8') as f:
    f.write(f"<GDAL_WMTS>\n  <GetCapabilitiesUrl>{capabilities_url.replace('&', '&amp;')}</GetCapabilitiesUrl>\n  <Layer>{layer_id}</Layer>\n  <TileMatrixSet>{chosen}</TileMatrixSet>\n</GDAL_WMTS>\n")

driver = ogr.GetDriverByName('GPKG')
ds = driver.CreateDataSource('area_cutline.gpkg')
srs = osr.SpatialReference(); srs.ImportFromEPSG(5367)
lyr = ds.CreateLayer('area', srs, ogr.wkbPolygon)
feat = ogr.Feature(lyr.GetLayerDefn())
feat.SetGeometry(ogr.CreateGeometryFromWkt(os.environ['AREA_WKT']))
lyr.CreateFeature(feat)
feat = None; ds = None
PY

